"""Strict primitive returns and actual linked-table API calls."""
CORE=r'''
function executeHash7(row){const [kind,capacity,operations,keys,values]=row.arguments,textKeys=kind==='text-number';function check(ok,message){if(!ok)throw Error(message);}function project(value){check(textKeys?Number.isInteger(value)&&value>=-2147483648&&value<=2147483647:typeof value==='string','Preserve the selected generic value type');return value;}const actor=new HashTable(capacity),other=new HashTable(capacity);check(other.Put(keys[0],values[0])===undefined,'Put returns undefined');const present=actor.Contains(keys[0]);check(typeof present==='boolean'&&!present,'New table instances own independent empty state');const results=[null],seen=[];for(let i=1;i<operations.length;++i){const operation=operations[i],key=keys[i];if(!seen.includes(key))seen.push(key);let result;if(operation==='Put'){check(actor.Put(key,values[i])===undefined,'Put returns undefined');result=null;}else if(operation==='Get'){try{result=project(actor.Get(key));}catch(error){if(!(error instanceof RangeError))throw error;result={error:'missing'};}}else if(operation==='Remove'){result=actor.Remove(key);check(typeof result==='boolean','Remove returns a boolean');}else if(operation==='Contains'){result=actor.Contains(key);check(typeof result==='boolean','Contains returns a boolean');}else throw Error('Unknown operation');results.push(result);}const finalEntries=[];for(const key of seen){try{finalEntries.push([key,project(actor.Get(key))]);}catch(error){if(!(error instanceof RangeError))throw error;}}return {actual:{results,finalEntries},mutationOk:true};}
'''
